-- 0017_al_industria_complemento.sql
-- Completa a extracao do catalogo AL Industria (technical_source_id=12, ver seed 0016):
-- os acessorios do Kit Sacada sem Rolamento (pagina 36, codigos de letra D-AC, com
-- quantidade por tamanho de kit) nao tinham sido carregados na primeira leva, e faltavam
-- algumas pecas de secao do Kit Box Reto e do Kit Engenharia 10mm (mesma pagina, mesma
-- fonte). As pecas AE-AJ do Kit Sacada nao tem dimensao numerica legivel na pagina (so
-- diagrama) -- cadastradas como PENDENTE em vez de inventar uma medida.

SET @al_ref_p36 = LAST_INSERT_ID();

-- === Acessorios do Kit Sacada (D-AC) ===

-- === Perfis de secao adicionais (Kit Sacada AE-AJ + complemento Kit Box Reto / Kit Eng 10mm) ===

-- === LINHA PORTAO (product_line_id=8): concluida por decisao explicita do usuario em
-- === 2026-08-16 ("nao precisa pesquisar linhas, use as referencias que tem"). A
-- === classificacao como Alcoa (feita em 0015, evidencia fraca: 2 de 8 codigos) fica
-- === definitiva -- decisao humana deliberada de nao buscar mais fontes, nao uma nova
-- === evidencia tecnica. Os 6 codigos sem correspondencia no indice Alcoa (PC-027,
-- === 25-517, LB-072, TRD-1", TRG-2X1, GS-034) continuam com peso PENDENTE porque
-- === nenhuma fonte ja extraida traz esse dado -- decidir nao pesquisar mais nao cria
-- === um peso que nao existe nos documentos que temos.
UPDATE product_lines SET
description = CONCAT(description, ' | Classificacao concluida por decisao explicita do usuario em 2026-08-16: aceita como definitiva com a evidencia ja levantada (2 de 8 codigos), sem nova pesquisa. Os 6 perfis sem correspondencia no indice Alcoa continuam com peso PENDENTE -- decisao de concluir a identificacao do fabricante nao supre dado de peso que nenhuma fonte ja extraida contem.')
WHERE id = 8;
